import importlib.util, itertools, random, sys, time
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

def classes(pp):
    d = {}
    for q, v in enumerate(pp):
        d.setdefault(v, []).append(q)
    return sorted(sorted(v) for v in d.values())

def moore_unbounded(n, trans, accept):
    ones = sum(accept)
    if ones == 0 or ones == n:
        part = [0]*n; blocks = 1
    else:
        part = accept[:]; blocks = 2
    while True:
        getter = part.__getitem__; marks = {}; newp = [0]*n; c = 0
        for q in range(n):
            sig = (part[q],) + tuple(map(getter, trans[q]))
            i = marks.get(sig)
            if i is None:
                i = c; c += 1; marks[sig] = i
            newp[q] = i
        if c == blocks or c == n:
            return newp, c
        part, blocks = newp, c

def random_reachable_dfa(n, sigma, rnd):
    """All states reachable from 0."""
    trans = [[0]*sigma for _ in range(n)]
    reached = [0]
    order = list(range(1, n))
    rnd.shuffle(order)
    for q in range(n):
        for c in range(sigma):
            if reached and rnd.random() < 0.7:
                trans[q][c] = rnd.choice(reached)
            elif order:
                trans[q][c] = order.pop()
            else:
                trans[q][c] = rnd.randrange(n)
    # ensure every state is reachable: rebuild via BFS assignment
    for i, q in enumerate(range(1, n)):
        pass
    # verify reachability; if some state unreachable, point an edge at it
    for target in range(1, n):
        for _ in range(50):
            seen = {0}; stack = [0]
            while stack:
                x = stack.pop()
                for t in trans[x]:
                    if t not in seen:
                        seen.add(t); stack.append(t)
            if target in seen:
                break
            src = rnd.choice(sorted(seen))
            trans[src][rnd.randrange(sigma)] = target
    accept = [rnd.randint(0, 1) for _ in range(n)]
    return trans, accept

def lang_equal(n1, t1, a1, n2, t2, a2, sigma, depth):
    # compare accepted words up to `depth`
    def words(depth):
        for L in range(depth+1):
            for tup in itertools.product(range(sigma), repeat=L):
                yield tup
    for w in words(depth):
        s = 0
        for x in w: s = t1[s][x]
        r1 = a1[s]
        s = 0
        for x in w: s = t2[s][x]
        r2 = a2[s]
        if bool(r1) != bool(r2):
            return False
    return True

rnd = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 3)
bad = 0
t0 = time.time()
trials = int(sys.argv[2]) if len(sys.argv) > 2 else 800
for trial in range(trials):
    n = rnd.randint(1, 40)
    sigma = rnd.randint(1, 4)
    trans, accept = random_reachable_dfa(n, sigma, rnd)
    ref, rb = moore_unbounded(n, trans, accept)
    got, gb = m.hopcroft(n, sigma, trans, accept[:] if 0 < sum(accept) < n else [0]*n,
                         2 if 0 < sum(accept) < n else 1)
    if classes(ref) != classes(got):
        bad += 1; print('HOPCROFT MISMATCH', n, sigma)
    acc, nxt, dist = m.minimize(n, sigma, trans, accept)
    if len(acc) != rb:
        bad += 1; print('SIZE MISMATCH', len(acc), rb, n, sigma, accept, trans)
    if not lang_equal(n, trans, accept, len(acc), nxt, acc, sigma, 6):
        bad += 1; print('LANGUAGE MISMATCH', n, sigma)
    # distances
    from collections import deque
    rev = [[] for _ in range(len(acc))]
    for q in range(len(acc)):
        for t in nxt[q]:
            rev[t].append(q)
    d = [None]*len(acc); dq = deque()
    for q in range(len(acc)):
        if acc[q]: d[q] = 0; dq.append(q)
    while dq:
        u = dq.popleft()
        for p in rev[u]:
            if d[p] is None: d[p] = d[u]+1; dq.append(p)
    if d != dist:
        bad += 1; print('DIST MISMATCH')
print('%d trials, %d problems, %.1fs' % (trials, bad, time.time()-t0))

# force the hopcroft fallback path inside minimize()
old = m.MOORE_ROUNDS
m.MOORE_ROUNDS = 1
bad2 = 0
for trial in range(trials):
    n = rnd.randint(2, 40)
    sigma = rnd.randint(1, 4)
    trans, accept = random_reachable_dfa(n, sigma, rnd)
    ref, rb = moore_unbounded(n, trans, accept)
    acc, nxt, dist = m.minimize(n, sigma, trans, accept)
    if len(acc) != rb or not lang_equal(n, trans, accept, len(acc), nxt, acc, sigma, 6):
        bad2 += 1
m.MOORE_ROUNDS = old
print('fallback path (MOORE_ROUNDS=1): %d problems' % bad2)
